package com.medtrack.inventory.repository; import com.medtrack.inventory.entity.InventoryJournalEntry; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface InventoryJournalEntryRepository extends JpaRepository<InventoryJournalEntry,UUID>{@EntityGraph(attributePaths="lines") Page<InventoryJournalEntry> findAll(Pageable pageable);@EntityGraph(attributePaths={"lines","lines.batch","lines.warehouse"}) @Query("select distinct entry from InventoryJournalEntry entry left join fetch entry.lines where entry.id=:id") Optional<InventoryJournalEntry> findWithLinesById(@Param("id") UUID id);}
